body.content:
:root {
  --color-background: #f4f3ef;
  --color-foreground: #1a1a1a;
  --color-accent: #c84b31;
}

.dark {
  --color-background: #111110;
  --color-foreground: #f0ede8;
  --color-accent: #e05c3f;
}

useEffect(() => {
  const root = document.documentElement;
  Object.entries(colors).forEach(([key, value]) => {
    root.style.setProperty(`--color-${key}`, value);
  });
}, [colors]);

useEffect(() => {
  const ctx = gsap.context(() => {
    gsap.from('.card', {
      y: 40,
      opacity: 0,
      stagger: 0.08,
      duration: 0.7,
      ease: 'expo.out',
      scrollTrigger: {
        trigger: '.cards',
        start: 'top 85%',
      },
    });
  }, ref);
  return () => ctx.revert();
}, []);

class AppError extends Error {
  constructor(
    public code: string,
    public message: string,
    public status: number = 400,
  ) {
    super(message);
  }
}

// Usage
throw new AppError('USER_NOT_FOUND', 'No user with that ID', 404);
